"""Undirected graph backed by adjacency sets (SPEC.md, Approach A)."""

from __future__ import annotations

from collections import deque


class Graph:
    """Simple undirected graph over integer nodes ``0 … nodes-1``.

    Each node maps to a set of its neighbours, so memory is proportional
    to nodes + edges and neighbour iteration is proportional to degree.
    Self-loops are permitted and stored as ``u in adj[u]``.
    """

    def __init__(self, nodes: int) -> None:
        if nodes < 0:
            raise ValueError("node count must be non-negative")
        self._adj: list[set[int]] = [set() for _ in range(nodes)]
        self._edges = 0

    # -- helpers ---------------------------------------------------------

    def _check(self, u: int) -> None:
        if not isinstance(u, int) or isinstance(u, bool):
            raise TypeError(f"node id must be an int, got {type(u).__name__}")
        if not 0 <= u < len(self._adj):
            raise IndexError(f"node {u} out of range for graph with {len(self._adj)} nodes")

    # -- public interface ------------------------------------------------

    def add_edge(self, u: int, v: int) -> None:
        self._check(u)
        self._check(v)
        if v in self._adj[u]:
            return  # already present; undirected so u in adj[v] too
        self._adj[u].add(v)
        self._adj[v].add(u)  # no-op for self-loops
        self._edges += 1

    def has_edge(self, u: int, v: int) -> bool:
        self._check(u)
        self._check(v)
        return v in self._adj[u]

    def neighbors(self, u: int) -> list[int]:
        self._check(u)
        return sorted(self._adj[u])

    def node_count(self) -> int:
        return len(self._adj)

    def edge_count(self) -> int:
        return self._edges

    def shortest_path(self, u: int, v: int) -> list[int] | None:
        self._check(u)
        self._check(v)
        if u == v:
            return [u]
        parent: dict[int, int] = {u: u}
        queue = deque([u])
        while queue:
            cur = queue.popleft()
            for nxt in self._adj[cur]:
                if nxt in parent:
                    continue
                parent[nxt] = cur
                if nxt == v:
                    path = [v]
                    while path[-1] != u:
                        path.append(parent[path[-1]])
                    path.reverse()
                    return path
                queue.append(nxt)
        return None
